   require(status is not None,\'owned harness did not reap after exact pidfd kill\')\\n        finally:\\n            if pidfd>=0:os.close(pidfd)\\n    raw,outpin=held(stdout,131072);_,errpin=held(stderr,32768)\\n    return {\'held_elf_path\':str(path),\'fd_exec\':True,\'started_utc\':started,\'finished_utc\':utc(),\\n            \'child_pid\':pid,\'child_reaped\':status is not None,\'wait_status\':status,\\n            \'returncode\':os.waitstatus_to_exitcode(status) if status is not None else None,\\n            \'timed_out\':timed_out,\'stdout\':outpin,\'stderr\':errpin},raw\\n\\n\\ndef validate_result(raw,plan,arm):\\n    require(arm in ARMS,\'unknown comparison arm\')\\n    expected=plan[\'arms\'][arm];names=expected[\'cases\']\\n    listener_names=[\'authorized_snapshot_dispatched_and_released\',\'maker_error_reply_then_same_grant_recovers\',\\n                    \'wrong_token_revokes_without_response\',\'unsupported_active_operation_revokes\',\\n                    \'peer_hup_revokes_queued_input_rights\',\'service_owner_hup_revokes\',\\n                    \'single_request_deadline_revokes\',\'suspend_ack_detach_same_lease_reattach\',\\n                    \'unexpected_owner_control_data_revokes\']\\n    lease_names=([\'foreign_CLONE_VM_CLONE_FILES\',\'partial_lease_initialization_EMFILE_cleanup\'] if arm==\'lease-preimage\'\\n                 else [\'foreign_CLONE_VM_CLONE_FILES\',\'foreign_CLONE_VM_private_fdtable\',\\n                       \'foreign_fork_COW\',\'partial_lease_initialization_EMFILE_cleanup\'])\\n    require(names==(listener_names if arm==\'listener\' else lease_names),\'exact reviewed case plan required\')\\n    lines=raw.decode(\'ascii\').splitlines()\\n    require(len(lines)==len(names)+1 and all(lines),\'exact case records and one terminal required\')\\n    records=[json.loads(line) for line in lines]\\n    for name,seen in zip(names,records[:-1]):\\n        if arm==\'listener\':\\n            require(seen=={\'case\':name,\'state\':\'